-- Only the verified local disposable harness runs this fixture; all changes roll back.
create function public.qb_id(text) returns uuid language sql immutable as $$select md5('question-bank-v250-'||$1)::uuid$$;
create function public.qb_assert(boolean,text) returns void language plpgsql as $$begin if $1 is distinct from true then raise exception 'QB FAIL: %',$2;end if;raise notice 'PASS: %',$2;end$$;
create function public.qb_reject(text,text) returns void language plpgsql as $$begin begin execute $1;exception when others then if sqlstate=$2 or position($2 in sqlerrm)>0 then raise notice 'PASS: denied %',$2;return;end if;raise;end;raise exception 'QB FAIL expected denial: %',$2;end$$;
insert into public.organization_groups(id,name,slug) values(qb_id('group'),'QB synthetic','question-bank-v250-synthetic'),(qb_id('group-b'),'QB external','question-bank-v250-external');
insert into public.organizations(id,name,group_id) values(qb_id('a'),'QB A',qb_id('group')),(qb_id('b'),'QB B',qb_id('group-b'));
insert into auth.users(id,email) select qb_id(u),u||'-qb@example.invalid' from unnest(array['owner','admin','super','member','outsider','inactive']) u;
insert into public.platform_users(id,auth_user_id,full_name,username,email,access_profile,group_id,status)
select qb_id('platform-'||u),qb_id(u),'Synthetic '||u,'qb-'||u,u||'-qb@example.invalid',(case when u='super' then 'super_admin' when u in ('inactive','outsider') then 'admin' else u end)::public.membership_role,case when u='super' then null when u='outsider' then qb_id('group-b') else qb_id('group') end,(case when u='inactive' then 'inactive' else 'active' end)::public.platform_user_status from unnest(array['owner','admin','super','member','outsider','inactive']) u;
insert into public.organization_memberships(organization_id,user_id,role) values(qb_id('a'),qb_id('owner'),'owner'),(qb_id('a'),qb_id('admin'),'admin'),(qb_id('a'),qb_id('member'),'member'),(qb_id('a'),qb_id('inactive'),'admin'),(qb_id('b'),qb_id('outsider'),'admin') on conflict(organization_id,user_id) do update set role=excluded.role;
create temp table qb_state(key text primary key,value jsonb);
grant all on qb_state to authenticated,service_role,anon;
create temp table qb_preserved as select id,to_jsonb(i) data from public.assessment_items i;
set local role anon;
select qb_reject('select public.load_m51c_item_bank_workspace(qb_id(''a''))','42501');
select qb_reject('select public.approve_and_publish_question_bank_proposal(qb_id(''a''),qb_id(''missing''))','42501');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub','',true);
select qb_reject('select public.load_m51c_item_bank_workspace(qb_id(''a''))','42501');
select set_config('request.jwt.claim.sub',qb_id('inactive')::text,true);
select qb_reject('select public.load_m51c_item_bank_workspace(qb_id(''a''))','42501');
select set_config('request.jwt.claim.sub',qb_id('member')::text,true);
select qb_reject('select public.load_m51c_item_bank_workspace(qb_id(''a''))','42501');
select set_config('request.jwt.claim.sub',qb_id('outsider')::text,true);
select qb_reject('select public.load_m51c_item_bank_workspace(qb_id(''a''))','42501');
select set_config('request.jwt.claim.sub',qb_id('owner')::text,true);
insert into qb_state values('workspace',public.load_m51c_item_bank_workspace(qb_id('a')));
select qb_assert((select value#>>'{permissions,canPublishOrganization}'='true' and value#>>'{permissions,canPublishGlobal}'='false' and value#>>'{permissions,canAdminister}'='true' from qb_state where key='workspace'),'owner retains company authority, policy consultation and cannot publish global');
select qb_assert((select bool_and(x ? 'familyId' and x ? 'options' and x ? 'correctOptionId' and x ? 'explanation') from qb_state,jsonb_array_elements(value->'items') x where key='workspace'),'authorized catalog includes actual family, full content and answer');
select qb_assert((select bool_and(x->'applicationCount'='null' and x->'excludedTechnicalIncidentCount'='null') from qb_state,jsonb_array_elements(value->'items') x where key='workspace'),'missing snapshot remains null, never zero applications/incidents');
select qb_assert((select bool_and((x->>'compositionItems')::integer+2=(x->>'requiredItems')::integer and x->>'diversityReserve'='2' and length(x->>'blueprintName')>0) from qb_state,jsonb_array_elements(value->'gaps') x where key='workspace'),'coverage uses recognizable model and separates composition/reserve');
insert into qb_state select 'gap',x from qb_state,jsonb_array_elements(value->'gaps') x where key='workspace' and (x->>'deficit')::integer>0 limit 1;
insert into qb_state select 'need',public.prepare_question_bank_generation(qb_id('a'),(value->>'blueprintId')::uuid,value->>'dimension') from qb_state where key='gap';
select qb_assert((select public.prepare_question_bank_generation(qb_id('a'),(value->>'blueprintId')::uuid,value->>'dimension')->>'generationNeedId'=(select value->>'generationNeedId' from qb_state where key='need') from qb_state where key='gap'),'preparation reuses same concrete need without AI');
select qb_reject('select public.prepare_question_bank_generation(qb_id(''b''),qb_id(''missing''),''knowledge'')','42501');
select qb_reject('select public.prepare_question_bank_generation(qb_id(''a''),qb_id(''missing''),''knowledge'')','M51C_GENERATION_NEED_NOT_AVAILABLE');
insert into qb_state select 'fake',public.create_m51c_fake_generation_request(qb_id('a'),(value->>'blueprintId')::uuid,value->>'dimension',2,'organization','qb-synthetic-1') from qb_state where key='gap';
insert into qb_state values('generated',public.load_m51c_item_bank_workspace(qb_id('a')));
insert into qb_state select 'proposal',x from qb_state,jsonb_array_elements(value->'proposals') x where key='generated' order by x->>'id' limit 1;
insert into qb_state select 'proposal2',x from qb_state,jsonb_array_elements(value->'proposals') x where key='generated' and x->>'id'<>(select value->>'id' from qb_state where key='proposal') limit 1;
select qb_assert((select bool_and(x->>'targetScope'='organization' and x#>>'{provenance,synthetic}'='true' and jsonb_array_length(x#>'{item,options}')=4) from qb_state,jsonb_array_elements(value->'proposals') x where key='generated'),'synthetic origin/destination and historical four-choice content preserved');
select qb_assert((select bool_and(x->>'producedQuantity'='2' and length(x->>'competencyLabel')>0 and x ? 'createdAt') from qb_state,jsonb_array_elements(value->'requests') x where key='generated'),'history includes context, date, requested/produced counts');
select qb_reject(format('select public.review_m51c_item_proposal(%L,''reject'','''')',(select value->>'id' from qb_state where key='proposal')),'M51C_REVIEW_REASON_REQUIRED');
select qb_reject(format('select public.review_m51c_item_proposal(%L,''request_changes'',''ok'')',(select value->>'id' from qb_state where key='proposal')),'M51C_REVIEW_REASON_REQUIRED');
-- Controlled fixture makes one ordinary proposal and one explicit exception.
reset role;
update public.assessment_item_generation_proposals set status='proposed',validation_result='{"valid":true,"reasonCodes":["STRUCTURE_VALID"]}' where id=(select (value->>'id')::uuid from qb_state where key='proposal');
update public.assessment_item_generation_proposals set status='duplicate_candidate',validation_result='{"valid":true,"reasonCodes":["STRONG_SIMILARITY_REVIEW_REQUIRED"]}' where id=(select (value->>'id')::uuid from qb_state where key='proposal2');
set local role authenticated;
select qb_reject(format('select public.approve_and_publish_question_bank_proposal(qb_id(''b''),%L)',(select value->>'id' from qb_state where key='proposal')),'42501');
select qb_reject(format('select public.review_m51c_item_proposal(%L,''approve'','''')',(select value->>'id' from qb_state where key='proposal2')),'M51C_EXCEPTION_REASON_REQUIRED');
reset role;
update public.assessment_item_generation_proposals set proposed_item=proposed_item-'correctOptionId' where id=(select (value->>'id')::uuid from qb_state where key='proposal2');
set local role authenticated;
select qb_reject(format('select public.approve_and_publish_question_bank_proposal(qb_id(''a''),%L,''Exceção devidamente revisada'')',(select value->>'id' from qb_state where key='proposal2')),'M51C_INVALID_PROPOSAL_CONTENT');
reset role;
select qb_assert(not exists(select 1 from public.assessment_item_generation_reviews where proposal_id=(select (value->>'id')::uuid from qb_state where key='proposal2')),'failed combined operation cannot leave an approval behind');
update public.assessment_item_generation_proposals set proposed_item=(select value->'item' from qb_state where key='proposal2') where id=(select (value->>'id')::uuid from qb_state where key='proposal2');
set local role authenticated;
select qb_reject(format('select public.publish_m51c_approved_proposals(qb_id(''a''),array[%L::uuid])',(select value->>'id' from qb_state where key='proposal')),'M51C_HUMAN_REVIEW_REQUIRED');
insert into qb_state select 'published',public.approve_and_publish_question_bank_proposal(qb_id('a'),(value->>'id')::uuid,'') from qb_state where key='proposal';
select qb_assert((select value->>'count'='1' from qb_state where key='published'),'explicit approve/dispose accepts empty ordinary rationale');
select qb_assert((select public.approve_and_publish_question_bank_proposal(qb_id('a'),(value->>'id')::uuid,'')->>'count'='1' from qb_state where key='proposal'),'replay returns same publication');
select qb_reject(format('select public.review_m51c_item_proposal(%L,''reject'',''Rejeição posterior indevida'')',(select value->>'id' from qb_state where key='proposal')),'M51C_PROPOSAL_LOCKED');
select public.review_m51c_item_proposal((select (value->>'id')::uuid from qb_state where key='proposal2'),'approve','Exceção revisada: contexto técnico distinto confirmado nesta fixture');
select qb_reject(format('select public.publish_m51c_approved_proposals(qb_id(''a''),array[%L::uuid,qb_id(''foreign'')])',(select value->>'id' from qb_state where key='proposal2')),'M51C_PROPOSAL_SCOPE_MISMATCH');
reset role;
select qb_assert((select count(*)=1 and bool_and(rationale='' and review_version='question-bank-human-review-2.0.0') from public.assessment_item_generation_reviews where proposal_id=(select (value->>'id')::uuid from qb_state where key='proposal')),'one explicit empty-rationale human review with snapshot/version, idempotent');
select qb_assert((select count(*)=2 from public.verification_audit_events where payload->>'proposal_id'=(select value->>'id' from qb_state where key='proposal') and action in ('m51c_item_proposal_reviewed','m51c_item_published_after_human_review')),'approval and publication remain separate audited facts');
select qb_assert((select status='approved' from public.assessment_item_generation_proposals where id=(select (value->>'id')::uuid from qb_state where key='proposal2')),'invalid batch rolls back and leaves unselected/unpublished approved proposal intact');
select qb_assert((select count(*)=1 from public.assessment_items where provenance->>'proposalId'=(select value->>'id' from qb_state where key='proposal')),'one published version only');
select qb_assert(not exists(select 1 from qb_preserved old join public.assessment_items i using(id) where old.data is distinct from to_jsonb(i)),'existing item content/state/history untouched');
select qb_assert(not has_function_privilege('authenticated','private.question_bank_workspace_before_v250(uuid)','execute') and not has_function_privilege('anon','public.load_m51c_item_bank_workspace(uuid)','execute'),'private legacy reader and anonymous content access revoked');
-- Reduced authority/global/cross-tenant isolation.
set local role authenticated; select set_config('request.jwt.claim.sub',qb_id('super')::text,true);
insert into qb_state select 'globalfake',public.create_m51c_fake_generation_request(qb_id('a'),(value->>'blueprintId')::uuid,value->>'dimension',1,'global','qb-global-test') from qb_state where key='gap';
insert into qb_state values('globalworkspace',public.load_m51c_item_bank_workspace(qb_id('a')));
insert into qb_state select 'globalproposal',x from qb_state,jsonb_array_elements(value->'proposals') x where key='globalworkspace' and x->>'targetScope'='global' limit 1;
select qb_assert((select value#>>'{permissions,canPublishGlobal}'='true' and value#>>'{permissions,canAdminister}'='true' from qb_state where key='globalworkspace'),'super retains existing global authority');
select set_config('request.jwt.claim.sub',qb_id('owner')::text,true);
select qb_reject(format('select public.approve_and_publish_question_bank_proposal(qb_id(''a''),%L,''Exceção com revisão contextual'')',(select value->>'id' from qb_state where key='globalproposal')),'42501');
select qb_reject('select private.question_bank_publish_before_v250(qb_id(''a''),array[qb_id(''missing'')])','42501');
select set_config('request.jwt.claim.sub',qb_id('outsider')::text,true);
select qb_assert((select not exists(select 1 from jsonb_array_elements(public.load_m51c_item_bank_workspace(qb_id('b'))->'items') x where x->>'organizationId'=qb_id('a')::text)),'company content excluded from other tenant catalog');
select qb_reject(format('select public.review_m51c_item_proposal(%L,''approve'','''')',(select value->>'id' from qb_state where key='proposal2')),'42501');
-- Real external boundary: deterministic output only, never a live model.
reset role;
update public.assessment_item_generation_needs set status='open' where id=(select (value->>'generationNeedId')::uuid from qb_state where key='need');
update public.assessment_ai_policies set generation_enabled=true,provider='openai-responses',model='approved-synthetic-model',monthly_limit_cents=1000,maximum_cost_per_request_cents=100,maximum_requests_per_day=20,cooldown_seconds=0 where organization_id=qb_id('a');
set local role authenticated; select set_config('request.jwt.claim.sub',qb_id('owner')::text,true);
select qb_reject(format('select public.request_m51c_item_generation(qb_id(''a''),%L,1,''organization'',1,''qb-no-quote'')',(select value->>'generationNeedId' from qb_state where key='need')),'PT_QUOTE_REQUIRED');
insert into qb_state values('quote',public.prisma_tokens('quote',qb_id('a'),'{"functionName":"position_assessment_items","quantity":1}'));
insert into qb_state select 'external',public.request_m51c_item_generation(qb_id('a'),(select (value->>'generationNeedId')::uuid from qb_state where key='need'),1,'organization',1,'qb-paid-boundary',(value->>'id')::uuid) from qb_state where key='quote';
select qb_assert((select public.request_m51c_item_generation(qb_id('a'),(select (value->>'generationNeedId')::uuid from qb_state where key='need'),1,'organization',1,'qb-paid-boundary',(value->>'id')::uuid)->>'replayed'='true' from qb_state where key='quote'),'request idempotency reuses reservation without new paid call');
reset role;
select qb_assert((select count(*)=1 and sum(amount)=2000 from private.prisma_token_reservations where organization_id=qb_id('a') and operation_id=(select (value->>'requestId')::uuid from qb_state where key='external')),'exactly one existing tariff reservation of 2000 Tokens Prisma');
set local role service_role;
insert into qb_state select 'complete',public.complete_m51c_external_generation((select (value->>'requestId')::uuid from qb_state where key='external'),jsonb_build_array((value->'item')||jsonb_build_object('key','QB-EXTERNAL-SYNTHETIC','stem','Como escolher uma estratégia técnica de transação neste cenário controlado?')),'{"costCents":1,"provider":"synthetic-test","inputTokens":10,"outputTokens":10}') from qb_state where key='proposal';
select public.complete_m51c_external_generation((select (value->>'requestId')::uuid from qb_state where key='external'),jsonb_build_array((select value->'item' from qb_state where key='proposal')),'{"costCents":1}');
reset role;
select qb_assert((select status='charged' from private.prisma_token_reservations where operation_id=(select (value->>'requestId')::uuid from qb_state where key='external')),'valid delivery settles commercial reservation');
select qb_assert((select count(*)=1 and sum(amount)=-2000 from private.prisma_token_movements where organization_id=qb_id('a') and kind='debit'),'delivery replay cannot double charge');
select qb_assert((select bool_and(status<>'published') from public.assessment_item_generation_proposals where generation_request_id=(select (value->>'requestId')::uuid from qb_state where key='external')),'generation never automatically publishes proposals');
select qb_assert(not has_function_privilege('authenticated','public.complete_m51c_external_generation(uuid,jsonb,jsonb)','execute') and not has_function_privilege('authenticated','private.question_bank_request_before_tokens(uuid,uuid,integer,text,integer,text)','execute'),'client cannot settle or bypass token reservation');
-- Failed/uncertain results and negative commercial gates keep the same approved policy.
update public.assessment_item_generation_needs set status='open' where id=(select (value->>'generationNeedId')::uuid from qb_state where key='need');
set local role authenticated; select set_config('request.jwt.claim.sub',qb_id('owner')::text,true);
select qb_reject(format('select public.request_m51c_item_generation(qb_id(''a''),%L,1,''organization'',null,''qb-unknown-cost'',%L)',(select value->>'generationNeedId' from qb_state where key='need'),(select value->>'id' from qb_state where key='quote')),'M51C_UNKNOWN_COST');
select qb_reject(format('select public.request_m51c_item_generation(qb_id(''a''),%L,1,''organization'',101,''qb-cost-cap'',%L)',(select value->>'generationNeedId' from qb_state where key='need'),(select value->>'id' from qb_state where key='quote')),'M51C_REQUEST_COST_CEILING_EXCEEDED');
insert into qb_state values('quote2',public.prisma_tokens('quote',qb_id('a'),'{"functionName":"position_assessment_items","quantity":1}'));
reset role; update private.prisma_token_quotes set expires_at=now()-interval '1 second' where id=(select (value->>'id')::uuid from qb_state where key='quote2');
set local role authenticated;
select qb_reject(format('select public.request_m51c_item_generation(qb_id(''a''),%L,1,''organization'',1,''qb-expired-quote'',%L)',(select value->>'generationNeedId' from qb_state where key='need'),(select value->>'id' from qb_state where key='quote2')),'PT_QUOTE_EXPIRED');
reset role;update private.prisma_token_quotes set expires_at=now()+interval '10 minutes' where id=(select (value->>'id')::uuid from qb_state where key='quote2');
update private.prisma_token_accounts set active=false where organization_id=qb_id('a');
set local role authenticated;
select qb_reject(format('select public.request_m51c_item_generation(qb_id(''a''),%L,1,''organization'',1,''qb-account-disabled'',%L)',(select value->>'generationNeedId' from qb_state where key='need'),(select value->>'id' from qb_state where key='quote2')),'PT_ACCOUNT_DISABLED');
reset role;update private.prisma_token_accounts set active=true where organization_id=qb_id('a');
update private.prisma_token_lots set remaining=0 where organization_id=qb_id('a');
set local role authenticated;
select qb_reject(format('select public.request_m51c_item_generation(qb_id(''a''),%L,1,''organization'',1,''qb-balance-zero'',%L)',(select value->>'generationNeedId' from qb_state where key='need'),(select value->>'id' from qb_state where key='quote2')),'PT_INSUFFICIENT_BALANCE');
reset role;update private.prisma_token_lots set remaining=100000 where organization_id=qb_id('a');
set local role authenticated;
insert into qb_state select 'external-fail',public.request_m51c_item_generation(qb_id('a'),(select (value->>'generationNeedId')::uuid from qb_state where key='need'),1,'organization',1,'qb-failure-boundary',(value->>'id')::uuid) from qb_state where key='quote2';
reset role;set local role service_role;
select public.fail_m51c_external_generation((select (value->>'requestId')::uuid from qb_state where key='external-fail'),'synthetic_failure_without_delivery');
select public.fail_m51c_external_generation((select (value->>'requestId')::uuid from qb_state where key='external-fail'),'synthetic_failure_without_delivery');
reset role;
select qb_assert((select status='released' from private.prisma_token_reservations where operation_id=(select (value->>'requestId')::uuid from qb_state where key='external-fail')),'failure without delivery releases commercial reservation');
select qb_assert((select count(*)=1 from private.prisma_token_movements where kind='release' and reference_id=(select id from private.prisma_token_reservations where operation_id=(select (value->>'requestId')::uuid from qb_state where key='external-fail'))),'failure replay records one release only');
select qb_assert(not exists(select 1 from public.assessment_item_generation_requests where organization_id=qb_id('a') and idempotency_key in ('qb-no-quote','qb-unknown-cost','qb-cost-cap','qb-expired-quote','qb-account-disabled','qb-balance-zero')),'denied generation rolls back request, budget reservation and commercial mutation');
